// فصل 02 از کتاب — تبدیل‌شده از نسخهٔ HTML؛ ویرایش دستی لازم نیست.
// Chapter 02 of the book — converted from the HTML edition; generated file.

export const n = 2;
export const num = "02";
export const title = "نصب و هویت — ستاپ حرفه‌ای Git در ۲۰۲۶";
export const label = "فصل ۲ · نصب و هویت";
export const part = 0;
export const html = "<p class=\"lead\">هر کامیت نام و ایمیل را داخل خودش ذخیره می‌کند. اگر این دو را غلط بگذاری، تاریخچه مال کس دیگری به نظر می‌رسد. این فصل را یک‌بار درست تنظیم کن.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>Git را روی Windows / macOS / Linux نصب و نسخه را چک کنی</li>\n<li><code>user.name</code> و <code>user.email</code> را درست — و ترجیحاً محلی — تنظیم کنی</li>\n<li>SSH Key بسازی، به GitHub اضافه کنی و با <code>gh auth</code> وارد شوی</li>\n<li>کامیت‌ها را با SSH sign کنی (جایگزین مدرن GPG)</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">🛠️ نصب Git ۲.۵۱+</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">نصب — لینوکس / macOS / Windows</span></div><pre><span style=\"color: #959077\"># Debian / Ubuntu</span>\nsudo<span style=\"color: #F8F8F2\"> </span>apt<span style=\"color: #F8F8F2\"> </span>update<span style=\"color: #F8F8F2\"> </span><span style=\"color: #FF4689\">&amp;&amp;</span><span style=\"color: #F8F8F2\"> </span>sudo<span style=\"color: #F8F8F2\"> </span>apt<span style=\"color: #F8F8F2\"> </span>install<span style=\"color: #F8F8F2\"> </span>-y<span style=\"color: #F8F8F2\"> </span>git<span style=\"color: #F8F8F2\"> </span>gh\n\n<span style=\"color: #959077\"># macOS</span>\nbrew<span style=\"color: #F8F8F2\"> </span>install<span style=\"color: #F8F8F2\"> </span>git<span style=\"color: #F8F8F2\"> </span>gh\n\n<span style=\"color: #959077\"># Windows (پاورشل به‌عنوان Admin)</span>\nwinget<span style=\"color: #F8F8F2\"> </span>install<span style=\"color: #F8F8F2\"> </span>Git.Git<span style=\"color: #F8F8F2\"> </span>GitHub.cli\n\ngit<span style=\"color: #F8F8F2\"> </span>--version<span style=\"color: #F8F8F2\">    </span><span style=\"color: #959077\"># باید ۲.۵۱ یا جدیدتر باشد</span>\ngh<span style=\"color: #F8F8F2\"> </span>--version\n</pre></div>\n<p>در VS Code: از Command Palette (<code>Ctrl+Shift+P</code>) بنویس <code>Git: Show Git Output</code>. اگر Git پیدا نشود، مسیر را در <code>git.path</code> تنظیم کن.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🪪 هویت — دو لایه</span></span></h2>\n<p class=\"keep-next\">دو هویت جدا وجود دارد و باید یکی باشند:</p>\n<ol>\n<li><strong>هویت Git</strong> — همان <code>user.name</code> و <code>user.email</code> که داخل هر کامیت نوشته می‌شود.</li>\n<li><strong>حساب GitHub</strong> — ایمیلی که در Settings گیت‌هاب ثبت کرده‌ای.</li>\n</ol>\n<p class=\"keep-next\">اگر ایمیل کامیت با ایمیل حساب یکی نباشد، کنار کامیت در GitHub آواتار خاکستری می‌بینی و نشان <strong>Verified</strong> (تأیید امضا) نمی‌آید.</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">پیکربندی هویت</span></div><pre><span style=\"color: #959077\"># سراسری — فقط اگر یک هویت داری</span>\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>--global<span style=\"color: #F8F8F2\"> </span>user.name<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;rezaian-dev&quot;</span>\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>--global<span style=\"color: #F8F8F2\"> </span>user.email<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;mrezaian.dev@gmail.com&quot;</span>\n\n<span style=\"color: #959077\"># بهتر: هویت داخل هر مخزن (توصیهٔ تیمی)</span>\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>user.name<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;rezaian-dev&quot;</span>\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>user.email<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;mrezaian.dev@gmail.com&quot;</span>\n\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>--global<span style=\"color: #F8F8F2\"> </span>init.defaultBranch<span style=\"color: #F8F8F2\"> </span>main\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>--global<span style=\"color: #F8F8F2\"> </span>pull.rebase<span style=\"color: #F8F8F2\"> false</span>\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>--global<span style=\"color: #F8F8F2\"> </span>fetch.prune<span style=\"color: #F8F8F2\"> true</span>\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>--global<span style=\"color: #F8F8F2\"> </span>rerere.enabled<span style=\"color: #F8F8F2\"> true</span>\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>--global<span style=\"color: #F8F8F2\"> </span>core.editor<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;code --wait&quot;</span>\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>--global<span style=\"color: #F8F8F2\"> </span>alias.st<span style=\"color: #F8F8F2\"> </span>status\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>--global<span style=\"color: #F8F8F2\"> </span>alias.lg<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;log --oneline --graph --decorate --all&quot;</span>\n</pre></div>\n<div class=\"callout callout-warn\"><div class=\"callout-title\">ایمیل مخفی GitHub</div>\n<p>اگر نمی‌خواهی ایمیلت در تاریخچهٔ عمومی دیده شود، از noreply گیت‌هاب استفاده کن:</p>\n<p><code>12345678+rezaian-dev@users.noreply.github.com</code></p>\n<p>در Settings → Emails گزینهٔ <em>Block command line pushes that expose my email</em> را روشن کن.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🔑 SSH — درِ جلویی GitHub</span></span></h2>\n<p class=\"keep-next\">HTTPS با token کار می‌کند اما SSH برای کار روزانه تمیزتر است.</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">ساخت کلید Ed25519</span></div><pre>ssh-keygen<span style=\"color: #F8F8F2\"> </span>-t<span style=\"color: #F8F8F2\"> </span>ed25519<span style=\"color: #F8F8F2\"> </span>-C<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;mrezaian.dev@gmail.com&quot;</span>\n<span style=\"color: #959077\"># Enter — passphrase قوی بگذار</span>\n\n<span style=\"color: #F8F8F2\">eval </span><span style=\"color: #E6DB74\">&quot;</span><span style=\"color: #66D9EF\">$(</span>ssh-agent<span style=\"color: #F8F8F2\"> </span>-s<span style=\"color: #66D9EF\">)</span><span style=\"color: #E6DB74\">&quot;</span>\nssh-add<span style=\"color: #F8F8F2\"> </span>~/.ssh/id_ed25519\n\n<span style=\"color: #959077\"># کلید عمومی را کپی کن</span>\ncat<span style=\"color: #F8F8F2\"> </span>~/.ssh/id_ed25519.pub\n</pre></div>\n<p class=\"keep-next\">در GitHub: <strong>Settings → SSH and GPG keys → New SSH key</strong>. بعد:</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">تست اتصال</span></div><pre>ssh<span style=\"color: #F8F8F2\"> </span>-T<span style=\"color: #F8F8F2\"> </span>git@github.com\n<span style=\"color: #959077\"># Hi rezaian-dev! You&#39;ve successfully authenticated...</span>\n</pre></div>\n<p>در VS Code وقتی Clone می‌کنی، اگر remote با <code>git@github.com:</code> شروع شود از همین کلید استفاده می‌شود.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">✍️ امضای کامیت با SSH — استاندارد ۲۰۲۶</span></span></h2>\n<p class=\"keep-next\">GPG هنوز معتبر است اما <strong>SSH signing</strong> ساده‌تر است و همان کلید را دوباره مصرف می‌کند.</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">فعال‌سازی امضا</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>--global<span style=\"color: #F8F8F2\"> </span>gpg.format<span style=\"color: #F8F8F2\"> </span>ssh\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>--global<span style=\"color: #F8F8F2\"> </span>user.signingkey<span style=\"color: #F8F8F2\"> </span>~/.ssh/id_ed25519.pub\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>--global<span style=\"color: #F8F8F2\"> </span>commit.gpgsign<span style=\"color: #F8F8F2\"> true</span>\ngit<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> </span>--global<span style=\"color: #F8F8F2\"> </span>tag.gpgsign<span style=\"color: #F8F8F2\"> true</span>\n</pre></div>\n<p>همان کلید عمومی را در GitHub به‌عنوان <em>Signing Key</em> هم اضافه کن. بعد از آن، کامیت‌هایت نشان <strong>Verified</strong> می‌گیرند.</p>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">VS Code</div>\n<p>در Settings بگذار:</p>\n<p><code>git.enableCommitSigning: true</code></p>\n<p>دکمهٔ Commit از همین تنظیم پیروی می‌کند — لازم نیست هر بار پرچم <code>-S</code> بزنی.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🐙 ورود با GitHub CLI</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">gh auth</span></div><pre>gh<span style=\"color: #F8F8F2\"> </span>auth<span style=\"color: #F8F8F2\"> </span>login\n<span style=\"color: #959077\"># GitHub.com → SSH → Login with browser</span>\n\ngh<span style=\"color: #F8F8F2\"> </span>auth<span style=\"color: #F8F8F2\"> </span>status\ngh<span style=\"color: #F8F8F2\"> </span>api<span style=\"color: #F8F8F2\"> </span>user<span style=\"color: #F8F8F2\"> </span>--jq<span style=\"color: #F8F8F2\"> </span>.login<span style=\"color: #F8F8F2\">    </span><span style=\"color: #959077\"># rezaian-dev</span>\n</pre></div>\n<p>از این به بعد <code>gh repo create</code>، <code>gh pr create</code> و <code>gh run list</code> بدون token دستی کار می‌کنند.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🧩 تنظیمات VS Code که Senior می‌چیند</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">.vscode/settings.json — گیت</span></div><pre><span style=\"color: #F8F8F2\">{</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.enabled&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">true</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.autofetch&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">true</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.confirmSync&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">false</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.enableSmartCommit&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">false</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.enableCommitSigning&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">true</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.untrackedChanges&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #E6DB74\">&quot;separate&quot;</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.branchProtection&quot;</span><span style=\"color: #F8F8F2\">: [</span><span style=\"color: #E6DB74\">&quot;main&quot;</span><span style=\"color: #F8F8F2\">, </span><span style=\"color: #E6DB74\">&quot;master&quot;</span><span style=\"color: #F8F8F2\">],</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.branchProtectionPrompt&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #E6DB74\">&quot;alwaysCommitToNewBranch&quot;</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.rebaseWhenSync&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">false</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;scm.defaultViewMode&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #E6DB74\">&quot;tree&quot;</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;diffEditor.ignoreTrimWhitespace&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">false</span>\n<span style=\"color: #F8F8F2\">}</span>\n</pre></div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🧩 افزونهٔ گیت VS Code — اتاق فرمان روزانه</span></span></h2>\n<p class=\"keep-next\">Git داخل VS Code سه لایه دارد. این کتاب هر فرمان را با <strong>هر دو مسیر</strong> یاد می‌دهد: ترمینال و این افزونه‌ها.</p>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>لایه</th>\n<th>شناسهٔ افزونه</th>\n<th>نقش</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Git توکار</strong></td>\n<td>همراه VS Code</td>\n<td>Source Control، Stage، Commit، Branch، Sync</td>\n</tr>\n<tr>\n<td><strong>GitHub Pull Requests</strong></td>\n<td><code>GitHub.vscode-pull-request-github</code></td>\n<td>Clone از GitHub، Checkout PR، ریویو اینلاین، Merge</td>\n</tr>\n<tr>\n<td><strong>Git Graph</strong> یا <strong>GitLens</strong></td>\n<td><code>mhutchie.git-graph</code> / <code>eamodio.gitlens</code></td>\n<td>DAG رنگی، blame خطی، مقایسهٔ کامیت‌ها</td>\n</tr>\n<tr>\n<td><strong>GitHub Actions</strong></td>\n<td><code>github.vscode-github-actions</code></td>\n<td>وضعیت workflow کنار ادیتور</td>\n</tr>\n</tbody>\n</table></div><p class=\"keep-next\">نصب از خود ادیتور:</p>\n<ol>\n<li><code>Ctrl+Shift+X</code> → Extensions</li>\n<li>جست‌وجو: <code>GitHub Pull Requests</code> → Install</li>\n<li>جست‌وجو: <code>Git Graph</code> → Install</li>\n<li>Accounts (پایین Activity Bar) → <strong>Sign in to GitHub</strong></li>\n<li class=\"keep-next\"><code>Ctrl+Shift+G</code> باید پنل Source Control را باز کند — خانهٔ روزانهٔ Git در این کتاب؛ فصل ۱۰ و ۱۱ آن را تا تسلط کامل می‌روند.</li>\n</ol>\n<div class=\"cols\">\n<div class=\"col\"><div class=\"col-title\">🖥️ VS Code Git</div>\n<p><strong>Commit:</strong> جعبهٔ پیام → <code>Ctrl+Enter</code>\n<strong>شاخه:</strong> کلیک روی <code>main</code> در نوار وضعیت\n<strong>Sync:</strong> آیکون ↻ کنار نام شاخه\n<strong>PR:</strong> آیکون GitHub در Activity Bar</p>\n</div>\n<div class=\"col\"><div class=\"col-title\">⌨️ Terminal</div>\n<p><code>git commit -m &quot;...&quot;</code>\n<code>git switch -c feat/x</code>\n<code>git push -u origin HEAD</code>\n<code>gh pr create --fill</code></p>\n</div>\n</div>\n<p>قانون این کتاب: مفهوم را در ترمینال بفهم؛ کار روزانه را در VS Code انجام بده. Senior هر دو را بلداست.</p>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Junior — چرا SSH بهتر از HTTPS است؟</strong> کلید روی دیسک می‌ماند، passphrase در agent کش می‌شود، و token PAT را هر چند ماه عوض نمی‌کنی.</p>\n<p><strong>Mid — تفاوت user.email و حساب GitHub؟</strong> Git فیلد را داخل شیء commit می‌نویسد. GitHub با همان ایمیل کامیت را به پروفایل وصل می‌کند.</p>\n<p><strong>Senior — چرا امضا مهم است؟</strong> بدون امضا هر کسی می‌تواند با <code>user.name</code> تو کامیت جعلی بسازد. Verified یعنی کلید ثبت‌شده در GitHub آن شیء را امضا کرده.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li><code>git --version</code> حداقل ۲.۵۱ است</li>\n<li><code>user.name</code> / <code>user.email</code> با GitHub یکی است</li>\n<li><code>ssh -T git@github.com</code> سلام می‌دهد</li>\n<li>کامیت تست با نشان Verified ساخته‌ای</li>\n<li>VS Code Signing و branch protection روشن است</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> سه درخت Git — جایی که ۸۰٪ سردرگمی متولد می‌شود.</p></div>";
export default { n, num, title, label, part, html };
